import{_ as a,c as r,o,a5 as c}from"./chunks/framework.DuCYAsAJ.js";const d=JSON.parse('{"title":"搜索逻辑：模式、分页与补全","description":"","frontmatter":{"title":"搜索逻辑：模式、分页与补全","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#6.1","branch":"main","level":1,"order":6.1},"headers":[],"relativePath":"posts/projects/zfeed/06-search-rpc-service/01-search-logic-modes-pagination-and-hydration.md","filePath":"posts/projects/zfeed/06-search-rpc-service/01-search-logic-modes-pagination-and-hydration.md","lastUpdated":1779632679000}'),t={name:"posts/projects/zfeed/06-search-rpc-service/01-search-logic-modes-pagination-and-hydration.md"};function i(n,e,l,p,h,s){return o(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="搜索逻辑-模式、分页与补全" tabindex="-1">搜索逻辑：模式、分页与补全 <a class="header-anchor" href="#搜索逻辑-模式、分页与补全" aria-label="Permalink to &quot;搜索逻辑：模式、分页与补全&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchcontentslogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchcontentslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchlogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchuserslogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchuserslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchuserslogic.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchuserslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go</a></li></ul></details><p><code>search-rpc</code> 服务实现了多模式搜索引擎，同时支持传统基于 cursor 的分页和稳定的基于快照的分页。本文说明一次搜索请求的端到端处理流程，从查询归一化到结果补全。</p><h2 id="搜索请求流程" tabindex="-1">搜索请求流程 <a class="header-anchor" href="#搜索请求流程" aria-label="Permalink to &quot;搜索请求流程&quot;">​</a></h2><p>搜索请求从 <code>front-api</code> 网关发起，并由 <code>SearchUsersLogic</code> 或 <code>SearchContentsLogic</code> 处理。流程包括归一化用户输入、选择合适的读取模式，以及决定使用缓存结果还是新鲜后端查询。</p><h3 id="数据流图" tabindex="-1">数据流图 <a class="header-anchor" href="#数据流图" aria-label="Permalink to &quot;数据流图&quot;">​</a></h3><p>下图展示从 HTTP 请求到最终补全响应的路径。</p><p>“搜索请求处理流程”</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchcontentslogic.go#L30-L75" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchcontentslogic.go#30-75</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L31-L59" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#31-59</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchuserslogic.go#L120-L140" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchuserslogic.go#120-140</a></p><h2 id="搜索模式与归一化" tabindex="-1">搜索模式与归一化 <a class="header-anchor" href="#搜索模式与归一化" aria-label="Permalink to &quot;搜索模式与归一化&quot;">​</a></h2><p>系统支持三种主要搜索模式，并通过 <code>normalizeSearchMode</code> 进行归一化。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L29-L40" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#29-40</a></p><table tabindex="0"><thead><tr><th>模式</th><th>行为</th><th>分页类型</th></tr></thead><tbody><tr><td><code>latest</code></td><td>按发布时间/创建时间倒序排序。</td><td>基于 cursor（<code>int64</code>）</td></tr><tr><td><code>relevance</code></td><td>按文本匹配分数排序。</td><td>基于快照（<code>PageToken</code>）</td></tr><tr><td><code>hybrid</code></td><td>相关性与热度（hot score）的加权组合。</td><td>基于快照（<code>PageToken</code>）</td></tr></tbody></table><p>查询归一化通过 <code>svcCtx.NormalizeQuery</code> 完成，<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L36-L36" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#36</a> 它会清洗搜索文本，并生成唯一的 <code>QueryHash</code>，用于缓存 key 生成和快照校验。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go#L19-L27" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go#19-27</a></p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L12-L15" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#12-15</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L29-L44" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#29-44</a></p><h2 id="分页策略" tabindex="-1">分页策略 <a class="header-anchor" href="#分页策略" aria-label="Permalink to &quot;分页策略&quot;">​</a></h2><p>系统根据搜索模式采用两种不同分页策略，以平衡性能和结果稳定性。</p><h3 id="_1-基于-cursor-的分页" tabindex="-1">1. 基于 cursor 的分页 <a class="header-anchor" href="#_1-基于-cursor-的分页" aria-label="Permalink to &quot;1. 基于 cursor 的分页&quot;">​</a></h3><p>用于 <code>latest</code> 模式。它依赖上一页最后一项的 <code>int64</code> ID（即 <code>Cursor</code>）从 MySQL 获取下一页。该策略对按时间排序的列表很高效，但如果两次分页请求之间发布了新内容，就容易出现“内容位移”。</p><ul><li>逻辑：<code>SearchContents</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L67-L73" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#67-73</a></li><li>Next Cursor：设置为当前结果集中最后一行的 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L131-L134" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#131-134</a></li></ul><h3 id="_2-基于快照的分页" tabindex="-1">2. 基于快照的分页 <a class="header-anchor" href="#_2-基于快照的分页" aria-label="Permalink to &quot;2. 基于快照的分页&quot;">​</a></h3><p>用于 <code>relevance</code> 和 <code>hybrid</code> 模式。由于相关性分数可能波动，系统会为 Top 结果（最多 <code>SearchSnapshotMaxItems</code>）创建一份“快照”，并存储到 Redis。</p><ul><li>快照创建：<code>createSearchSnapshot</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go#L63-L79" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go#63-79</a></li><li>PageToken：一个不透明的 base64 编码 JSON 对象，包含 <code>SnapshotID</code> 和当前 <code>Offset</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L24-L27" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#24-27</a></li><li>稳定性：后续携带相同 <code>SnapshotID</code> 的请求会从 Redis 快照读取数据，而不是重新查询数据库，确保用户翻页期间看到一致列表。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go#L81-L106" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go#81-106</a></li></ul><p>“分页与快照逻辑”</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L24-L27" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#24-27</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go#L19-L27" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go#19-27</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L50-L86" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#50-86</a></p><h2 id="结果补全" tabindex="-1">结果补全 <a class="header-anchor" href="#结果补全" aria-label="Permalink to &quot;结果补全&quot;">​</a></h2><p>搜索后端（MySQL 全文搜索或缓存）返回的原始行会被转换为丰富的 API 实体。</p><h3 id="用户搜索补全-isfollowing" tabindex="-1">用户搜索补全（<code>IsFollowing</code>） <a class="header-anchor" href="#用户搜索补全-isfollowing" aria-label="Permalink to &quot;用户搜索补全（`IsFollowing`）&quot;">​</a></h3><p>搜索用户时，<code>SearchUsersLogic</code> 会基于 <code>ViewerId</code> 为结果补全 <code>IsFollowing</code> 状态。</p><ol><li>批量查询：逻辑调用 <code>FollowRpc.BatchQueryFollowing</code>。[app/rpc/search/internal/logic/searchuserslogic.go:166-179]（测试中）/ <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchuserslogic.go#L120-L120" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchuserslogic.go#120</a></li><li>映射：遍历搜索结果，并附加 <code>interaction-rpc</code> 服务返回的关注状态。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L167-L176" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#167-176</a></li></ol><h3 id="内容搜索转换" tabindex="-1">内容搜索转换 <a class="header-anchor" href="#内容搜索转换" aria-label="Permalink to &quot;内容搜索转换&quot;">​</a></h3><p>内容行会被映射为 <code>SearchContentItem</code> 对象。该过程包括将数据库时间戳转换为 Unix 整数，并把作者元数据（姓名、头像）扁平化到响应中。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L118-L129" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#118-129</a></p><h2 id="快照生命周期与-pagetoken" tabindex="-1">快照生命周期与 PageToken <a class="header-anchor" href="#快照生命周期与-pagetoken" aria-label="Permalink to &quot;快照生命周期与 PageToken&quot;">​</a></h2><ol><li>初始请求：用户发送查询。系统检测到没有 <code>PageToken</code>，执行后端搜索，通过 <code>createSearchSnapshot</code> 将结果保存到 Redis，并返回第一页和 <code>NextPageToken</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L223-L261" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#223-261</a></li><li>后续请求：用户发送 <code>NextPageToken</code>。系统调用 <code>decodePageToken</code>，使用 <code>SnapshotID</code> 从 Redis 取回完整结果集，再基于 <code>Offset</code> 切片数组。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L109-L126" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#109-126</a></li><li>过期：快照拥有可配置 TTL（默认 60 秒，最大 90 秒）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L17-L21" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#17-21</a> 如果 Redis 中找不到快照，系统返回 <code>400 Bad Request</code>，提示用户重新发起搜索。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go#L90-L92" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go#90-92</a></li></ol><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L50-L107" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#50-107</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/snapshot.go#L81-L106" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/snapshot.go#81-106</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/pagination.go#L128-L140" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/pagination.go#128-140</a></p>',34)])])}const b=a(t,[["render",i]]);export{d as __pageData,b as default};
